/* The web's own page fitting of a print (App.html fitWideTables, fitBillPages, fitLogPages – taken as they are): each bill on one A4
 * page, each Log Book sheet on one page with the signatures at its foot, a too-wide table made to fit. Run in the print view. */
const kPrintFit = 'function fitWideTables(doc) {\nconst sheet = doc.querySelector(\'.sheet\'); if (!sheet) return;\nconst minPx = 6.4; // about 4.8 pt – smallest size still clear on paper\ndoc.querySelectorAll(\'.sheet table\').forEach(t => {\nif (t.closest(\'.billsheet\')) return;                       // bills have their own fitting\nt.style.zoom = \'\'; if (t.dataset.fitlay) { t.style.tableLayout = \'\'; delete t.dataset.fitlay; } t.querySelectorAll(\'[data-fs]\').forEach(c => { c.style.fontSize = \'\'; }); t.querySelectorAll(\'[data-fitws]\').forEach(c => { c.style.whiteSpace = \'\'; c.style.overflow = \'\'; c.style.wordBreak = \'\'; c.removeAttribute(\'data-fitws\'); });\n// a fixed-width table whose cells cut their text: let the columns take the room their text needs (then shrink to the page below)\nif (doc.defaultView.getComputedStyle(t).tableLayout === \'fixed\' && [...t.querySelectorAll(\'th, td\')].some(c => c.scrollWidth > c.clientWidth + 1)) { t.style.tableLayout = \'auto\'; t.dataset.fitlay = \'1\'; }\nconst box = t.parentElement, room = () => { const cs = doc.defaultView.getComputedStyle(box); return box.clientWidth - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0); }, wide = () => t.scrollWidth > room() + 1 || t.getBoundingClientRect().width > room() + 1;\nif (!wide()) return;\nconst cells = [...t.querySelectorAll(\'th, td\')];\nlet fs = parseFloat(doc.defaultView.getComputedStyle(t).fontSize) || 9;\ncells.forEach(c => { c.dataset.fs = parseFloat(doc.defaultView.getComputedStyle(c).fontSize) || fs; });\nlet k = 1;\nwhile (wide() && k > 0.55) { k -= 0.05; cells.forEach(c => { c.style.fontSize = Math.max(minPx, Number(c.dataset.fs) * k) + \'px\'; }); }\nif (wide()) { const z = room() / Math.max(t.scrollWidth, t.getBoundingClientRect().width); t.style.zoom = String(Math.max(0.5, z)); }\n});\n// a heading or cell whose text is cut by its column: let it wrap onto a second line instead\ndoc.querySelectorAll(\'.sheet table\').forEach(t => { if (t.closest(\'.billsheet\')) return; t.querySelectorAll(\'th, td\').forEach(c => { if (c.scrollWidth > c.clientWidth + 1 && !c.style.whiteSpace) { c.setAttribute(\'data-fitws\', \'1\'); c.style.whiteSpace = \'normal\'; c.style.overflow = \'visible\'; c.style.wordBreak = \'keep-all\'; } }); });\n}\nfunction fitBillPages(doc) {\n// each bill on ONE A4 page, as big as possible: shrink step by step and measure again each time\n// (a shrunk bill is laid out on a wider sheet – 192mm ÷ size – so fewer lines wrap: measure it exactly that way)\nconst mm = 3.7795, pageH = 258 * mm;\ndoc.querySelectorAll(\'.billsheet\').forEach(sh => {\nsh.style.zoom = \'\'; sh.style.minHeight = \'0\'; sh.style.width = \'192mm\'; // the printed width (A4 less margins)\nconst tall = () => sh.getBoundingClientRect().height;\nlet z = 1;\nif (tall() > pageH) {\nlet lo = 0.5, hi = 1;\nfor (let k = 0; k < 12; k++) { const m = (lo + hi) / 2; sh.style.zoom = String(m); sh.style.width = (192 / m) + \'mm\'; if (tall() > pageH) hi = m; else lo = m; }\nz = lo; sh.style.zoom = String(z);\n}\nsh.style.width = \'\';\nsh.style.minHeight = z < 1 ? (262 / z) + \'mm\' : \'\';\n});\n}\nfunction fitLogPages(doc) {\nconst sheets = doc.querySelectorAll(\'.lbsheet\'); if (!sheets.length) return;\nconst mm = 3.7795, st = doc.getElementById(\'orient\'), land = !!st && /landscape/.test(st.textContent);\nconst H = land ? 186 : 272;                                   // the printed height of A4 less its margins (189 / 275 mm), less 3 mm so that rounding never makes a second page\nsheets.forEach(sh => {\nconst sg = sh.querySelector(\'.lb-sign\');\nconst set = z => { sh.style.zoom = z < 1 ? String(z) : \'\'; sh.style.minHeight = \'0\'; if (sg) sg.style.paddingTop = (12 / z) + \'mm\'; };\nconst tall = () => sh.getBoundingClientRect().height;\nset(1); let z = 1;\nif (tall() > H * mm) {\nlet lo = 0.3, hi = 1;\nfor (let k = 0; k < 14; k++) { const m = (lo + hi) / 2; set(m); if (tall() > H * mm) hi = m; else lo = m; }\nz = lo; set(z);\n}\nsh.dataset.fit = String(Math.round(z * 1000) / 1000);\nsh.style.minHeight = (H / z) + \'mm\';                        // the sheet fills its page: the signatures at the foot\n});\n}';
